import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { marked } from 'marked';
import DOMPurify from 'dompurify';
import { Library, Copy, ExternalLink, Trash2, ChevronDown, Search, Download } from 'lucide-react';
import { StorageService, SavedSummary } from '../services/storage';
import { useToast } from '../popup';

function timeAgo(iso: string): string {
  try {
    const date  = new Date(iso);
    const diffMs = Date.now() - date.getTime();
    const sec    = Math.floor(diffMs / 1000);
    if (sec < 60)  return 'just now';
    const min = Math.floor(sec / 60);
    if (min < 60)  return `${min}m ago`;
    const hrs = Math.floor(min / 60);
    if (hrs < 24)  return `${hrs}h ago`;
    const days = Math.floor(hrs / 24);
    if (days < 7)  return `${days}d ago`;
    return date.toLocaleDateString();
  } catch { return 'unknown'; }
}

/** Safely render markdown to sanitized HTML */
function renderMarkdown(raw: string): string {
  const html = marked(raw) as string;
  return DOMPurify.sanitize(html);
}

/** Illustrated empty state SVG */
