import React, { useState, useEffect } from 'react';
import { TrendingUp, RefreshCw, AlertTriangle, FileText, Hash, Zap } from 'lucide-react';
import { ApiService, UsageData } from '../services/api';
import { StorageService, UserStats } from '../services/storage';

interface UsageTabProps {
  apiKey: string;
}

interface TabState {
  isLoading: boolean;
  error: string;
  usageData: UsageData | null;
  localStats: UserStats | null;
  lastRefresh: string;
  localStatsDate: string;
}

export const UsageTab: React.FC<UsageTabProps> = ({ apiKey }) => {
  const [state, setState] = useState<TabState>({
    isLoading: true,
    error: '',
    usageData: null,
    localStats: null,
    lastRefresh: '',
    localStatsDate: ''
  });

  useEffect(() => { loadUsageData(); }, [apiKey]);

  const loadUsageData = async () => {
    setState(prev => ({ ...prev, isLoading: true, error: '' }));
    try {
      const [usageData, localStats] = await Promise.all([
        ApiService.getUsageData(apiKey),
        StorageService.getUserStats()
      ]);
      await StorageService.saveLastUsageCheck();

      const localStatsDate = localStats?.lastUpdated
        ? formatDate(localStats.lastUpdated)
        : '';

      setState(prev => ({
        ...prev,
        usageData,
        localStats,
        lastRefresh: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        localStatsDate,
        isLoading: false
      }));
    } catch (error) {
      setState(prev => ({
        ...prev,
        error: error instanceof Error ? error.message : 'Failed to load usage data',
        isLoading: false
      }));
    }
  };

  const calculateUsagePercentage = (): number => {
    if (!state.usageData || state.usageData.monthlyLimit <= 0) return 0;
    return Math.min((state.usageData.currentUsage / state.usageData.monthlyLimit) * 100, 100);
  };

  const getUsageLevelClass = (): string => {
    const pct = calculateUsagePercentage();
    if (pct >= 90) return 'usage-high';
    if (pct >= 75) return 'usage-mid';
    return 'usage-low';
  };

  const formatNumber = (num: number): string => num.toLocaleString();

  const formatDate = (dateString: string): string => {
    try { return new Date(dateString).toLocaleDateString([], { month: 'short', day: 'numeric' }); }
    catch { return 'Unknown'; }
  };

  const getRemainingDays = (): number => {
    if (!state.usageData?.resetDate) return 0;
    try {
      const diff = Math.ceil((new Date(state.usageData.resetDate).getTime() - Date.now()) / 86400000);
      return Math.max(0, diff);
    } catch { return 0; }
  };

  const pct      = calculateUsagePercentage();
  const hasLimit = state.usageData && state.usageData.monthlyLimit > 0;
  const remaining = hasLimit
    ? Math.max(0, state.usageData!.monthlyLimit - state.usageData!.currentUsage)
    : 0;

  if (state.isLoading) {
    return (
      <div id="usage-tab" className="tab-pane active">
        <div className="usage-stats">
          <div className="skeleton-card skeleton-animate usage-skeleton">
            <div className="skeleton-block" style={{ width: '50%', height: 15, marginBottom: 18 }} />
            <div className="skeleton-block" style={{ width: '100%', height: 8,  marginBottom: 12 }} />
            <div className="skeleton-block" style={{ width: '60%', height: 18, margin: '0 auto 12px' }} />
          </div>
        </div>
      </div>
    );
  }

  return (
    <div id="usage-tab" className="tab-pane active">
      <div className="usage-stats">

        {/* Monthly usage card */}
        {state.usageData && (
          <div className="stat-card">
            <h3>
              <TrendingUp size={16} style={{ display: 'inline', marginRight: 6, verticalAlign: 'middle' }} />
              Monthly Usage
            </h3>

            {hasLimit && (
              <>
                <div className="usage-ring-wrap">
                  <div
                    className={`usage-ring ${getUsageLevelClass()}`}
                    style={{
                      ['--usage-pct' as string]: String(pct),
                      ['--ring-color' as string]:
                        pct >= 90 ? 'var(--usage-high)' : pct >= 75 ? 'var(--usage-mid)' : 'var(--usage-low)'
                    }}
                    role="img"
                    aria-label={`${Math.round(pct)} percent of monthly limit used`}
                  >
                    <span className="usage-ring-label">{Math.round(pct)}%</span>
                  </div>
                  <div className="usage-ring-caption">
                    <div className="usage-remaining">
                      {formatNumber(remaining)} summaries left
                    </div>
                    <div className="usage-sub">
                      {formatNumber(state.usageData.currentUsage)} / {formatNumber(state.usageData.monthlyLimit)} used
                      · Resets in {getRemainingDays()}d
                    </div>
                  </div>
                </div>
                <div className="usage-bar">
                  <div
                    id="usage-progress"
                    className={`progress-fill ${getUsageLevelClass()}`}
                    style={{ width: `${pct}%` }}
                  />
                </div>
              </>
            )}

            <div className="usage-numbers">
              <span id="usage-current">{formatNumber(state.usageData.currentUsage)}</span>
              {hasLimit ? (
                <> / <span id="usage-limit">{formatNumber(state.usageData.monthlyLimit)}</span> summaries</>
              ) : (
                <> summaries used</>
              )}
            </div>

            {hasLimit ? (
              <p className="usage-reset-note">
                Resets {formatDate(state.usageData.resetDate)} ({getRemainingDays()} days)
              </p>
            ) : (
              <p className="usage-reset-note">No monthly limit reported — plan may be unlimited.</p>
            )}

            {state.usageData.planType && (
              <p className="usage-plan-type">Plan: {state.usageData.planType}</p>
            )}
          </div>
        )}

        {/* Local activity card */}
        {state.localStats && (
          <div className="stat-card local-stats-card">
            <h3>Your Activity (local)</h3>
            <div className="local-stats-grid">
              <div className="stat-item">
                <span className="stat-label">
                  <FileText size={11} style={{ display: 'inline', marginRight: 4, verticalAlign: 'middle' }} />
                  Summaries
                </span>
                <span className="stat-value">{formatNumber(state.localStats.totalSummaries)}</span>
              </div>
              <div className="stat-item">
                <span className="stat-label">
                  <Hash size={11} style={{ display: 'inline', marginRight: 4, verticalAlign: 'middle' }} />
                  Words
                </span>
                <span className="stat-value">{formatNumber(state.localStats.wordsProcessed)}</span>
              </div>
              <div className="stat-item">
                <span className="stat-label">
                  <Zap size={11} style={{ display: 'inline', marginRight: 4, verticalAlign: 'middle' }} />
                  Tokens
                </span>
                <span className="stat-value">{formatNumber(state.localStats.tokensUsed)}</span>
              </div>
            </div>
          </div>
        )}

        {/* Usage warning */}
        {hasLimit && pct >= 80 && (
          <div className="error-message show usage-warning-banner">
            <AlertTriangle size={13} style={{ display: 'inline', marginRight: 6, verticalAlign: 'middle' }} />
            You&apos;re approaching your monthly limit. Consider upgrading your plan.
          </div>
        )}

        {/* Refresh button */}
        <button
          id="refresh-usage-btn"
          type="button"
          className="secondary-btn full-width refresh-usage-btn"
          onClick={loadUsageData}
          disabled={state.isLoading}
        >
          <RefreshCw size={13} strokeWidth={2} />
          {state.isLoading ? 'Refreshing…' : 'Refresh Usage Data'}
        </button>

        {/* Merged sync line — single timestamp */}
        {(state.lastRefresh || state.localStatsDate) && (
          <p className="usage-sync-line">
            {state.lastRefresh && <>Synced at {state.lastRefresh}</>}
            {state.lastRefresh && state.localStatsDate && <> · </>}
            {state.localStatsDate && <>Local stats: {state.localStatsDate}</>}
          </p>
        )}
      </div>

      {state.error && (
        <div className="error-message show" role="alert">{state.error}</div>
      )}
    </div>
  );
};
