import React, {
  useState, useEffect, useCallback, useRef,
  createContext, useContext
} from 'react';
import { createRoot } from 'react-dom/client';
import {
  PenLine, Bookmark, BarChart2,
  CheckCircle2, AlertCircle, X,
  Sun, Moon, Type, LayoutGrid, LogOut, Settings,
  ClipboardPaste, Eye, EyeOff
} from 'lucide-react';
import { StorageService, ThemePreference, UiPreferences } from './services/storage';
import { ApiService } from './services/api';
import { SummarizeTab } from './components/SummarizeTab';
import { UsageTab } from './components/UsageTab';
import { SavedSummariesTab } from './components/SavedSummariesTab';
import './popup.css';

/* ========= GLOBAL TOAST CONTEXT ========= */
export interface ToastOptions {
  message: string;
  type?: 'success' | 'error';
  duration?: number;
}
export type ShowToastFn = (opts: ToastOptions) => void;
export const ToastContext = createContext<ShowToastFn>(() => {});
export const useToast = () => useContext(ToastContext);

interface ToastState {
  visible: boolean;
  message: string;
  type: 'success' | 'error';
}

const ToastNotification: React.FC<{
  toast: ToastState;
  onDismiss: () => void;
}> = ({ toast, onDismiss }) => (
  <div className={`toast-notification ${toast.visible ? 'toast-visible' : ''} toast-${toast.type}`}>
    <span className="toast-icon">
      {toast.type === 'success'
        ? <CheckCircle2 size={14} strokeWidth={2.5} />
        : <AlertCircle size={14} strokeWidth={2.5} />}
    </span>
    <span className="toast-message">{toast.message}</span>
    {toast.visible && (
      <button type="button" className="toast-dismiss" onClick={onDismiss} aria-label="Dismiss">
        <X size={13} />
      </button>
    )}
    <div className="toast-progress" />
  </div>
);

/* ========= CONFIRM LOGOUT DIALOG ========= */
const ConfirmLogoutDialog: React.FC<{
  onCancel: () => void;
  onConfirm: () => void;
}> = ({ onCancel, onConfirm }) => (
  <div className="confirm-overlay" role="dialog" aria-modal="true" aria-labelledby="confirm-title">
    <div className="confirm-dialog">
      <div className="confirm-dialog-icon">
        <LogOut size={22} strokeWidth={2} />
      </div>
      <h3 id="confirm-title">Log out?</h3>
      <p>This will remove your API key from the extension. You'll need to enter it again to use Get TLDR.</p>
      <div className="confirm-dialog-actions">
        <button type="button" className="confirm-cancel-btn" onClick={onCancel}>Cancel</button>
        <button type="button" className="confirm-logout-btn" onClick={onConfirm}>Log out</button>
      </div>
    </div>
  </div>
);

/* ========= SETTINGS PANEL ========= */
const SettingsPanel: React.FC<{
  theme: ThemePreference;
  uiPrefs: UiPreferences;
  onToggleTheme: () => void;
  onToggleReadingFont: () => void;
  onToggleCompact: () => void;
  onLogout: () => void;
  onClose: () => void;
}> = ({ theme, uiPrefs, onToggleTheme, onToggleReadingFont, onToggleCompact, onLogout, onClose }) => {
  const panelRef = useRef<HTMLDivElement>(null);

  // Close on outside click
  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (panelRef.current && !panelRef.current.contains(e.target as Node)) {
        onClose();
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [onClose]);

  // Close on Escape
  useEffect(() => {
    const handler = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); };
    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, [onClose]);

  return (
    <div className="settings-panel" ref={panelRef} role="menu">
      <div className="settings-panel-header">Preferences</div>

      <button
        type="button"
        className="settings-panel-item"
        onClick={onToggleTheme}
        role="menuitem"
      >
        <span className="settings-panel-item-icon">
          {theme === 'dark' ? <Sun size={15} strokeWidth={2} /> : <Moon size={15} strokeWidth={2} />}
        </span>
        <span className="settings-panel-item-label">
          {theme === 'dark' ? 'Light mode' : 'Dark mode'}
        </span>
        <div className={`settings-toggle ${theme === 'light' ? 'on' : ''}`} aria-hidden />
      </button>

      <button
        type="button"
        className="settings-panel-item"
        onClick={onToggleReadingFont}
        role="menuitem"
      >
        <span className="settings-panel-item-icon">
          <Type size={15} strokeWidth={2} />
        </span>
        <span className="settings-panel-item-label">Reading font</span>
        <div className={`settings-toggle ${uiPrefs.readingFont ? 'on' : ''}`} aria-hidden />
      </button>

      <button
        type="button"
        className="settings-panel-item"
        onClick={onToggleCompact}
        role="menuitem"
      >
        <span className="settings-panel-item-icon">
          <LayoutGrid size={15} strokeWidth={2} />
        </span>
        <span className="settings-panel-item-label">Compact layout</span>
        <div className={`settings-toggle ${uiPrefs.compactDensity ? 'on' : ''}`} aria-hidden />
      </button>

      <button
        type="button"
        className="settings-panel-item"
        onClick={onLogout}
        role="menuitem"
      >
        <span className="settings-panel-item-icon">
          <LogOut size={15} strokeWidth={2} />
        </span>
        <span className="settings-panel-item-label">Log out</span>
      </button>
    </div>
  );
};

/* ========= SETUP STEP INDICATOR ========= */
const SetupStepIndicator: React.FC<{ step: number }> = ({ step }) => {
  const steps = ['Get key', 'Enter below', 'Done!'];
  return (
    <div className="setup-steps" aria-label="Setup progress">
      {steps.map((label, idx) => {
        const num = idx + 1;
        const isDone   = step > num;
        const isActive = step === num;
        return (
          <div key={num} className="setup-step-wrap">
            <div className={`setup-step ${isDone ? 'done' : ''} ${isActive ? 'active' : ''}`}>
              <div className="setup-step-dot">
                {isDone ? <CheckCircle2 size={12} strokeWidth={3} /> : num}
              </div>
              <span className="setup-step-label">{label}</span>
            </div>
            {idx < steps.length - 1 && (
              <div className={`setup-step-connector ${isDone ? 'filled' : ''}`} />
            )}
          </div>
        );
      })}
    </div>
  );
};

/* ========= APP ========= */
type Screen = 'setup' | 'main';
type Tab    = 'summarize' | 'saved' | 'usage';

interface AppState {
  screen: Screen;
  activeTab: Tab;
  apiKey: string;
  isLoading: boolean;
  error: string;
  theme: ThemePreference;
  savedCount: number;
  setupSuccess: boolean;
}

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    screen: 'setup',
    activeTab: 'summarize',
    apiKey: '',
    isLoading: false,
    error: '',
    theme: 'dark',
    savedCount: 0,
    setupSuccess: false
  });

  const [uiPrefs, setUiPrefs]             = useState<UiPreferences>({});
  const [showApiKey, setShowApiKey]       = useState(false);
  const [apiKeyInput, setApiKeyInput]     = useState('');
  const [showSettings, setShowSettings]   = useState(false);
  const [showLogoutDialog, setShowLogoutDialog] = useState(false);
  const [toast, setToast]                 = useState<ToastState>({ visible: false, message: '', type: 'success' });
  const toastTimerRef                     = useRef<ReturnType<typeof setTimeout> | null>(null);

  const showToast = useCallback((opts: ToastOptions) => {
    if (toastTimerRef.current) clearTimeout(toastTimerRef.current);
    setToast({ visible: true, message: opts.message, type: opts.type ?? 'success' });
    toastTimerRef.current = setTimeout(() => {
      setToast(prev => ({ ...prev, visible: false }));
    }, opts.duration ?? 2800);
  }, []);

  const handleDismissToast = useCallback(() => {
    if (toastTimerRef.current) clearTimeout(toastTimerRef.current);
    setToast(prev => ({ ...prev, visible: false }));
  }, []);

  // Cursor glow tracking
  const handleMouseMove = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
    const el = e.currentTarget as HTMLElement;
    el.style.setProperty('--mouse-x', `${e.clientX}px`);
    el.style.setProperty('--mouse-y', `${e.clientY}px`);
  }, []);

  const refreshSavedCount = useCallback(async () => {
    const list = await StorageService.getSavedSummaries();
    setState(prev => ({ ...prev, savedCount: list.length }));
  }, []);

  useEffect(() => {
    Promise.all([
      checkExistingApiKey(),
      initTheme(),
      initUiPrefs(),
      refreshSavedCount()
    ]).catch(console.error);

    const onStorageChange = (
      changes: { [key: string]: chrome.storage.StorageChange },
      area: string
    ) => {
      if (area === 'local' && changes.get_tldr_saved_summaries) refreshSavedCount();
    };
    chrome.storage.onChanged.addListener(onStorageChange);
    return () => chrome.storage.onChanged.removeListener(onStorageChange);
  }, [refreshSavedCount]);

  const initUiPrefs = async () => {
    const prefs = await StorageService.getUiPreferences();
    setUiPrefs(prefs);
    applyUiPrefs(prefs);
  };

  const applyUiPrefs = (prefs: UiPreferences) => {
    document.documentElement.setAttribute('data-reading-font', prefs.readingFont ? 'true' : 'false');
    document.documentElement.setAttribute('data-density', prefs.compactDensity ? 'compact' : 'normal');
  };

  const initTheme = async () => {
    const pref = await StorageService.getThemePreference();
    setState(prev => ({ ...prev, theme: pref }));
    applyTheme(pref);
    document.documentElement.setAttribute('data-ui', 'pro');
  };

  const applyTheme = (theme: ThemePreference) => {
    document.documentElement.setAttribute('data-theme', theme);
    if (!document.documentElement.getAttribute('data-ui')) {
      document.documentElement.setAttribute('data-ui', 'pro');
    }
  };

  const toggleTheme = async () => {
    setState(prev => {
      const next: ThemePreference = prev.theme === 'dark' ? 'light' : 'dark';
      applyTheme(next);
      StorageService.saveThemePreference(next);
      return { ...prev, theme: next };
    });
  };

  const toggleReadingFont = async () => {
    const next = !uiPrefs.readingFont;
    const prefs = { ...uiPrefs, readingFont: next };
    setUiPrefs(prefs);
    applyUiPrefs(prefs);
    await StorageService.saveUiPreferences({ readingFont: next });
  };

  const toggleCompactDensity = async () => {
    const next = !uiPrefs.compactDensity;
    const prefs = { ...uiPrefs, compactDensity: next };
    setUiPrefs(prefs);
    applyUiPrefs(prefs);
    await StorageService.saveUiPreferences({ compactDensity: next });
  };

  const checkExistingApiKey = async () => {
    try {
      const existing = await StorageService.getApiKey();
      if (existing) setState(prev => ({ ...prev, apiKey: existing, screen: 'main' }));
    } catch (e) { console.error('Error checking API key:', e); }
  };

  const validateAndSaveApiKey = async () => {
    if (!apiKeyInput.trim()) {
      setState(prev => ({ ...prev, error: 'Please enter an API key' }));
      return;
    }
    if (!apiKeyInput.startsWith('tl_')) {
      setState(prev => ({ ...prev, error: 'API key must start with "tl_"' }));
      return;
    }
    setState(prev => ({ ...prev, isLoading: true, error: '' }));
    try {
      const isValid = await ApiService.validateApiKey(apiKeyInput);
      if (isValid) {
        await StorageService.saveApiKey(apiKeyInput);
        setState(prev => ({ ...prev, apiKey: apiKeyInput, isLoading: false, setupSuccess: true, error: '' }));
        showToast({ message: 'API key saved — welcome!', type: 'success' });
        setTimeout(() => {
          setState(prev => ({ ...prev, screen: 'main', setupSuccess: false }));
        }, 900);
      } else {
        setState(prev => ({ ...prev, error: 'Invalid API key. Please check and try again.', isLoading: false }));
      }
    } catch {
      setState(prev => ({ ...prev, error: 'Failed to validate API key. Please try again.', isLoading: false }));
    }
  };

  const handleTabChange = (tab: Tab) => setState(prev => ({ ...prev, activeTab: tab }));

  // Two-step logout
  const requestLogout  = ()  => { setShowSettings(false); setShowLogoutDialog(true); };
  const cancelLogout   = ()  => setShowLogoutDialog(false);
  const confirmLogout  = async () => {
    setShowLogoutDialog(false);
    await StorageService.clearApiKey();
    setState(prev => ({ ...prev, screen: 'setup', apiKey: '', activeTab: 'summarize' }));
    setApiKeyInput('');
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') validateAndSaveApiKey();
  };

  const pasteApiKeyFromClipboard = async () => {
    try {
      const text = await navigator.clipboard.readText();
      if (text.trim()) setApiKeyInput(text.trim());
    } catch {
      setState(prev => ({ ...prev, error: 'Could not read clipboard. Paste manually.' }));
    }
  };

  // Step: 1=empty input, 2=loading/has input, 3=success
  const setupStep = !apiKeyInput.trim() ? 1 : state.isLoading ? 2 : state.setupSuccess ? 3 : 2;

  return (
    <ToastContext.Provider value={showToast}>
      <div id="root" onMouseMove={handleMouseMove}>

        {/* ---- SETUP SCREEN ---- */}
        {state.screen === 'setup' && (
          <div id="api-setup" className="screen">
            <div className="header">
              <img src="icons/icon48.png" alt="Get TLDR" className="logo" />
              <h1>Get TLDR</h1>
            </div>
            <div className="setup-content">
              <h2>Welcome!</h2>
              <p>Enter your API key to get started with AI-powered summarization.</p>

              <SetupStepIndicator step={setupStep} />

              {state.setupSuccess && (
                <div className="setup-success-banner" role="status">
                  <CheckCircle2 size={14} strokeWidth={2.5} />
                  Key validated — opening app…
                </div>
              )}

              <div className="input-group setup-actions-row">
                <div className="api-key-field">
                  <input
                    type={showApiKey ? 'text' : 'password'}
                    id="api-key-input"
                    placeholder="Enter your API key (tl_...)"
                    value={apiKeyInput}
                    onChange={e => setApiKeyInput(e.target.value)}
                    onKeyPress={handleKeyPress}
                    disabled={state.isLoading}
                    autoComplete="off"
                  />
                  <div className="api-key-field-actions">
                    <button
                      type="button"
                      className="icon-btn-sm"
                      onClick={() => setShowApiKey(v => !v)}
                      aria-label={showApiKey ? 'Hide API key' : 'Show API key'}
                    >
                      {showApiKey ? <EyeOff size={15} /> : <Eye size={15} />}
                    </button>
                    <button
                      type="button"
                      className="icon-btn-sm"
                      onClick={pasteApiKeyFromClipboard}
                      aria-label="Paste from clipboard"
                      title="Paste from clipboard"
                    >
                      <ClipboardPaste size={15} />
                    </button>
                  </div>
                </div>

                <button
                  id="validate-key-btn"
                  className={`primary-btn full-width ${state.isLoading ? 'loading' : ''}`}
                  onClick={validateAndSaveApiKey}
                  disabled={state.isLoading}
                  type="button"
                >
                  <span className="btn-text">Validate &amp; Save</span>
                  <span className="btn-loading">
                    <span className="loading-dots">
                      <span /><span /><span />
                    </span>
                    Validating…
                  </span>
                </button>
              </div>

              {state.error && (
                <div id="api-error" className="error-message show" role="alert">
                  {state.error}
                </div>
              )}

              <div className="help-text">
                <p>
                  Don't have an API key?{' '}
                  <a href="https://www.get-tldr.com" target="_blank" rel="noopener noreferrer">
                    Get one here
                  </a>
                </p>
              </div>
            </div>
          </div>
        )}

        {/* ---- MAIN APP SCREEN ---- */}
        {state.screen === 'main' && (
          <div id="main-app" className="screen">
            <div className="header">
              <img src="icons/icon48.png" alt="Get TLDR" className="logo" />
              <h1>Get TLDR</h1>

              {/* Single settings button */}
              <div className="settings-btn-wrap header-actions-group">
                <button
                  id="settings-btn"
                  type="button"
                  className="icon-btn"
                  onClick={() => setShowSettings(v => !v)}
                  aria-label="Settings"
                  aria-expanded={showSettings}
                  title="Settings"
                >
                  <Settings size={16} strokeWidth={2} />
                </button>

                {showSettings && (
                  <SettingsPanel
                    theme={state.theme}
                    uiPrefs={uiPrefs}
                    onToggleTheme={() => { toggleTheme(); setShowSettings(false); }}
                    onToggleReadingFont={() => { toggleReadingFont(); }}
                    onToggleCompact={() => { toggleCompactDensity(); }}
                    onLogout={requestLogout}
                    onClose={() => setShowSettings(false)}
                  />
                )}
              </div>
            </div>

            {/* Tab navigation */}
            <div className="tab-nav" role="tablist" aria-label="Main navigation">
              <button
                role="tab"
                aria-selected={state.activeTab === 'summarize'}
                className={`tab-btn ${state.activeTab === 'summarize' ? 'active' : ''}`}
                onClick={() => handleTabChange('summarize')}
              >
                <PenLine size={14} strokeWidth={2} />
                Summarize
              </button>
              <button
                role="tab"
                aria-selected={state.activeTab === 'saved'}
                className={`tab-btn ${state.activeTab === 'saved' ? 'active' : ''}`}
                onClick={() => handleTabChange('saved')}
              >
                <Bookmark size={14} strokeWidth={2} />
                Saved
                {state.savedCount > 0 && (
                  <span className="tab-badge" aria-label={`${state.savedCount} saved`}>
                    {state.savedCount > 99 ? '99+' : state.savedCount}
                  </span>
                )}
              </button>
              <button
                role="tab"
                aria-selected={state.activeTab === 'usage'}
                className={`tab-btn ${state.activeTab === 'usage' ? 'active' : ''}`}
                onClick={() => handleTabChange('usage')}
              >
                <BarChart2 size={14} strokeWidth={2} />
                Usage
              </button>
            </div>

            {/* Tab content */}
            <div key={state.activeTab} className="tab-content tab-content-animated" role="tabpanel">
              {state.activeTab === 'summarize' && (
                <SummarizeTab
                  apiKey={state.apiKey}
                  onSummarySaved={refreshSavedCount}
                />
              )}
              {state.activeTab === 'saved' && (
                <SavedSummariesTab
                  onSummariesChange={refreshSavedCount}
                  onGoToSummarize={() => handleTabChange('summarize')}
                />
              )}
              {state.activeTab === 'usage' && (
                <UsageTab apiKey={state.apiKey} />
              )}
            </div>

            <footer className="app-footer">
              © 2026{' '}
              <a href="https://www.get-tldr.com" target="_blank" rel="noopener noreferrer">
                get-tldr.com
              </a>
            </footer>
          </div>
        )}

        {/* Loading overlay */}
        {state.isLoading && (
          <div id="loading-overlay" className="overlay">
            <div className="spinner" />
            <p>Loading…</p>
          </div>
        )}
      </div>

      {/* Logout confirmation dialog */}
      {showLogoutDialog && (
        <ConfirmLogoutDialog onCancel={cancelLogout} onConfirm={confirmLogout} />
      )}

      <ToastNotification toast={toast} onDismiss={handleDismissToast} />
    </ToastContext.Provider>
  );
};

const container = document.getElementById('root');
if (container) {
  const root = createRoot(container);
  root.render(<App />);
}