import React, { useState, useEffect } from 'react';
import { marked } from 'marked';
import DOMPurify from 'dompurify';
import {
  PanelRight, ClipboardCopy, Share2, AlertTriangle, CheckCircle2,
  Link2, RotateCcw, ExternalLink, Hash, Zap, Clock, Info
} from 'lucide-react';
import { ApiService, PromptOption, SummaryResponse } from '../services/api';
import { StorageService } from '../services/storage';
import { useToast } from '../popup';

const FAVORITE_PROMPT_SLOTS = 3;

interface SummarizeTabProps {
  apiKey: string;
  onSummarySaved?: () => void;
}

interface TabState {
  currentUrl: string;
  currentTitle: string;
  prompts: PromptOption[];
  selectedPrompt: string;
  isLoading: boolean;
  isSummarizing: boolean;
  summary: SummaryResponse | null;
  error: string;
  pageAccessible: boolean;
  domainWarning?: string;
  sentUrl?: string;
  autoSaved: boolean;
}

interface ContextMenuSummaryData {
  summary: string;
  tokensUsed: number;
  wordCount: number;
  url: string;
  title: string;
}

interface ChromeMessage {
  type: string;
  data?: ContextMenuSummaryData;
}

function parsePageContext(url: string, title: string): { hostname: string; favicon: string } {
  try {
    const u = new URL(url);
    return {
      hostname: u.hostname.replace(/^www\./, ''),
      favicon: `https://www.google.com/s2/favicons?domain=${encodeURIComponent(u.hostname)}&sz=32`
    };
  } catch {
    return { hostname: title || 'Unknown page', favicon: '' };
  }
}

/** Safely render markdown to sanitized HTML */
function renderMarkdown(raw: string): string {
  const html = marked(raw) as string;
  return DOMPurify.sanitize(html);
}

/** Skeleton loader that mimics the Summarize tab layout */
const SummarizeSkeleton: React.FC = () => (
  <div className="skeleton-summarize" aria-busy="true" aria-label="Loading page details">
    {/* Current page chip skeleton */}
    <div className="skeleton-chip skeleton-animate">
      <div className="skeleton-circle" />
      <div className="skeleton-lines">
        <div className="skeleton-block" style={{ width: '60%', height: 12 }} />
        <div className="skeleton-block" style={{ width: '85%', height: 10 }} />
      </div>
    </div>
    {/* Prompt picker skeleton */}
    <div className="skeleton-chip skeleton-animate" style={{ gap: 8 }}>
      <div className="skeleton-block" style={{ width: '30%', height: 10 }} />
      <div className="skeleton-block" style={{ width: '30%', height: 10 }} />
      <div className="skeleton-block" style={{ width: '30%', height: 10 }} />
    </div>
    {/* Button skeleton */}
    <div className="skeleton-block skeleton-animate" style={{ height: 44, borderRadius: 999 }} />
  </div>
);

export const SummarizeTab: React.FC<SummarizeTabProps> = ({ apiKey, onSummarySaved }) => {
  const [state, setState] = useState<TabState>({
    currentUrl: 'Loading...',
    currentTitle: '',
    prompts: [],
    selectedPrompt: 'default',
    isLoading: true,
    isSummarizing: false,
    summary: null,
    error: '',
    pageAccessible: false,
    domainWarning: undefined,
    autoSaved: false
  });

  const showToast = useToast();

  useEffect(() => {
    initializeTab();

    const messageListener = (message: ChromeMessage) => {
      if (message.type === 'CONTEXT_MENU_SUMMARY' && message.data) {
        handleContextMenuSummary(message.data);
      }
    };

    chrome.runtime.onMessage.addListener(messageListener);
    return () => chrome.runtime.onMessage.removeListener(messageListener);
  }, [apiKey]);

  const handleContextMenuSummary = (data: ContextMenuSummaryData) => {
    setState((prev: TabState) => ({
      ...prev,
      summary: {
        summary: data.summary,
        tokensUsed: data.tokensUsed,
        wordCount: data.wordCount,
        processingTime: 0
      },
      currentUrl: data.url,
      currentTitle: `[Selected Text] ${data.title}`,
      isSummarizing: false,
      error: '',
      autoSaved: false
    }));
  };

  const initializeTab = async () => {
    setState((prev: TabState) => ({ ...prev, isLoading: true, error: '' }));
    try {
      const [pageAccessible, tab, lastPrompt, cachedPrompts] = await Promise.all([
        ApiService.isPageAccessible(),
        chrome.tabs.query({ active: true, currentWindow: true }).then(tabs => tabs[0]),
        StorageService.getLastSelectedPrompt(),
        StorageService.getCachedPrompts()
      ]);

      const currentUrl   = tab?.url   || 'Unknown';
      const currentTitle = tab?.title || 'Unknown';
      let domainWarning: string | undefined;

      try {
        const hostname = new URL(currentUrl).hostname.toLowerCase();
        domainWarning  = getDomainWarning(hostname) || undefined;
      } catch { /* ignore */ }

      if (cachedPrompts && Array.isArray(cachedPrompts) && cachedPrompts.length > 0) {
        const validSelected = lastPrompt && cachedPrompts.some((p: PromptOption) => p.id === lastPrompt)
          ? lastPrompt : 'default';
        setState((prev: TabState) => ({
          ...prev, currentUrl, currentTitle, prompts: cachedPrompts,
          selectedPrompt: validSelected, pageAccessible, domainWarning, isLoading: false
        }));
        ApiService.getPrompts(apiKey, false)
          .then(fresh => setState((prev: TabState) => ({ ...prev, prompts: fresh })))
          .catch(err  => console.warn('Background prompt refresh failed:', err));
      } else {
        const prompts = await ApiService.getPrompts(apiKey, true);
        const validSelected = lastPrompt && prompts.some(p => p.id === lastPrompt) ? lastPrompt : 'default';
        setState((prev: TabState) => ({
          ...prev, currentUrl, currentTitle, prompts,
          selectedPrompt: validSelected, pageAccessible, domainWarning, isLoading: false
        }));
      }
    } catch {
      setState((prev: TabState) => ({ ...prev, error: 'Failed to initialize tab', isLoading: false }));
    }
  };

  const getDomainWarning = (hostname: string): string | null => {
    const limited = [
      { patterns: /(^|\.)google\.com$/i,      message: 'Google pages often restrict direct content extraction; summarization may be limited.' },
      { patterns: /(^|\.)facebook\.com$/i,     message: 'Facebook is highly dynamic; extracted text may be incomplete.' },
      { patterns: /(^|\.)instagram\.com$/i,    message: 'Instagram content is mostly images; textual summary may be minimal.' },
      { patterns: /(^|\.)twitter\.com$/i,      message: 'Twitter timeline is dynamic; only visible loaded tweets may be summarized.' },
      { patterns: /(^|\.)x\.com$/i,            message: 'X (Twitter) timeline is dynamic; only visible loaded posts may be summarized.' },
      { patterns: /(^|\.)linkedin\.com$/i,     message: 'LinkedIn feeds use virtual scrolling; extraction may exclude off‑screen content.' },
      { patterns: /(^|\.)web\.whatsapp\.com$/i,message: 'WhatsApp Web is a protected app shell; message text may not be accessible.' },
      { patterns: /(^|\.)tiktok\.com$/i,       message: 'TikTok content is video-centric; textual extraction is limited.' },
      { patterns: /(^|\.)slack\.com$/i,        message: 'Slack web app content is dynamic and may not expose full history for extraction.' }
    ];
    for (const entry of limited) {
      if (entry.patterns.test(hostname)) return entry.message;
    }
    return null;
  };

  const handleSummarize = async () => {
    if (!state.pageAccessible) {
      setState((prev: TabState) => ({
        ...prev,
        error: 'Cannot summarize this type of page. Open a regular https:// article or page and try again.'
      }));
      return;
    }

    setState((prev: TabState) => ({ ...prev, isSummarizing: true, error: '', summary: null, autoSaved: false }));

    try {
      const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
      const currentUrl   = tab?.url   || state.currentUrl;
      const currentTitle = tab?.title || state.currentTitle;
      const tabId        = tab?.id;

      if (!currentUrl || !/^https?:\/\//i.test(currentUrl)) {
        throw new Error('Unable to access a valid web page URL to summarize');
      }

      const selectedPromptObj = state.prompts.find((p: PromptOption) => p.id === state.selectedPrompt);
      const promptText = selectedPromptObj?.prompt || 'Provide a concise summary of the main points in this content.';
      const isYouTube  = /(^|\.)youtube\.com\/watch/i.test(currentUrl) || /(^|\.)youtu\.be\//i.test(currentUrl);

      let summary: SummaryResponse;
      const startTime = Date.now();
      const canonicalUrl = ApiService.canonicalizeUrl(currentUrl);

      if (isYouTube && tabId) {
        const response = await chrome.runtime.sendMessage({
          type: 'SUMMARIZE_YOUTUBE_VIDEO',
          data: { url: currentUrl, title: currentTitle, prompt: promptText }
        });
        if (response.error) throw new Error(response.error);
        summary = { summary: response.summary, tokensUsed: response.tokensUsed, wordCount: response.wordCount, processingTime: 0 };
      } else {
        summary = await ApiService.summarizeContent(apiKey, { url: canonicalUrl, prompt: promptText, skipCache: false });
      }

      const processingTime = Date.now() - startTime;

      await StorageService.updateUserStats({
        totalSummaries: 1,
        wordsProcessed: summary.wordCount,
        tokensUsed: summary.tokensUsed
      });

      let autoSaved = false;
      try {
        await StorageService.saveSummary({
          title: currentTitle || 'Untitled Page',
          url: currentUrl || '',
          summary: summary.summary,
          prompt: selectedPromptObj?.prompt || 'Default prompt',
          tokensUsed: summary.tokensUsed,
          wordCount: summary.wordCount
        });
        autoSaved = true;
        onSummarySaved?.();
      } catch (saveError) {
        console.warn('Failed to auto-save summary:', saveError);
      }

      setState((prev: TabState) => ({
        ...prev, currentUrl, currentTitle, sentUrl: canonicalUrl,
        summary: { ...summary, processingTime }, isSummarizing: false, autoSaved
      }));
    } catch (error) {
      setState((prev: TabState) => ({
        ...prev,
        error: error instanceof Error ? error.message : 'Failed to summarize content',
        isSummarizing: false
      }));
    }
  };

  const selectPrompt = (promptId: string) => {
    setState((prev: TabState) => ({ ...prev, selectedPrompt: promptId }));
    StorageService.saveLastSelectedPrompt(promptId).catch(err =>
      console.warn('Could not persist selected prompt', err)
    );
  };

  const handleCopySummary = async (summary: string) => {
    try {
      await navigator.clipboard.writeText(summary);
      showToast({ message: 'Copied to clipboard!', type: 'success' });
    } catch {
      const ta = document.createElement('textarea');
      ta.value = summary;
      document.body.appendChild(ta);
      ta.select();
      document.execCommand('copy');
      document.body.removeChild(ta);
      showToast({ message: 'Copied to clipboard!', type: 'success' });
    }
  };

  const handleShareSummary = async (summary: string) => {
    const shareData = {
      title: 'AI Summary',
      text: `Summary of "${state.currentTitle}":\n\n${summary}`,
      url: state.currentUrl
    };
    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(`${shareData.text}\n\nSource: ${shareData.url}`);
        showToast({ message: 'Summary copied for sharing!', type: 'success' });
      }
    } catch (e) { console.error('Failed to share:', e); }
  };

  const handleOpenInSidebar = async () => {
    if (!state.summary) return;
    try {
      const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
      if (!tab.id) return;
      try { await chrome.scripting.executeScript({ target: { tabId: tab.id }, files: ['marked.min.js'] }); } catch { /* already injected */ }
      try { await chrome.scripting.executeScript({ target: { tabId: tab.id }, files: ['content-sidebar.js'] }); } catch { /* already injected */ }
      try { await chrome.scripting.insertCSS({ target: { tabId: tab.id }, files: ['content-sidebar.css'] }); } catch { /* already injected */ }
      await chrome.tabs.sendMessage(tab.id, {
        type: 'SHOW_SIDEBAR_SUMMARY',
        data: { summary: state.summary.summary, selectedText: '', tokensUsed: state.summary.tokensUsed, wordCount: state.summary.wordCount, url: state.currentUrl, title: state.currentTitle }
      });
      window.close();
    } catch {
      setState((prev: TabState) => ({ ...prev, error: 'Failed to open sidebar. Try refreshing the page and summarizing again.' }));
    }
  };

  const copyPageUrl = async () => {
    if (!state.currentUrl || state.currentUrl === 'Loading...') return;
    try {
      await navigator.clipboard.writeText(state.currentUrl);
      showToast({ message: 'Page link copied', type: 'success' });
    } catch { /* ignore */ }
  };

  const openCurrentPage = () => {
    if (state.currentUrl && /^https?:\/\//i.test(state.currentUrl)) {
      chrome.tabs.create({ url: state.currentUrl });
    }
  };

  // ---- Loading skeleton ----
  if (state.isLoading) {
    return (
      <div id="summarize-tab" className="tab-pane active">
        <SummarizeSkeleton />
      </div>
    );
  }

  const { hostname, favicon } = parsePageContext(state.currentUrl, state.currentTitle);
  const favoritePrompts    = state.prompts.slice(0, FAVORITE_PROMPT_SLOTS);
  const morePrompts        = state.prompts.slice(FAVORITE_PROMPT_SLOTS);
  const selectedPromptObj  = state.prompts.find(p => p.id === state.selectedPrompt);
  const containerClass     = `tab-pane active ${state.summary ? 'summary-top-layout' : ''}`;

  return (
    <div id="summarize-tab" className={containerClass}>

      {/* ---- Summarizing skeleton ---- */}
      {state.isSummarizing && !state.summary && (
        <div id="summary-result" className="result-section skeleton-wrapper skeleton-animate" aria-busy="true" aria-live="polite">
          <div className="result-header">
            <h3 className="text-muted-heading">Generating Summary…</h3>
          </div>
          <div className="summary-text" style={{ maxHeight: 'none' }}>
            <div className="skeleton-block" style={{ width: '92%' }} />
            <div className="skeleton-block" style={{ width: '87%' }} />
            <div className="skeleton-block" style={{ width: '83%' }} />
            <div className="skeleton-block" style={{ width: '58%' }} />
          </div>
        </div>
      )}

      {/* ---- Summary result ---- */}
      {state.summary && !state.isSummarizing && (
        <div id="summary-result" className="result-section">
          <div className="result-header">
            <h3>Summary</h3>
            <div className="result-actions">
              <button className="action-btn sidebar-btn" onClick={handleOpenInSidebar} title="Open in sidebar" type="button">
                <PanelRight size={14} strokeWidth={2} />
              </button>
              <button className="action-btn copy-btn" onClick={() => handleCopySummary(state.summary!.summary)} title="Copy to clipboard" type="button">
                <ClipboardCopy size={14} strokeWidth={2} />
              </button>
              <button className="action-btn share-btn" onClick={() => handleShareSummary(state.summary!.summary)} title="Share summary" type="button">
                <Share2 size={14} strokeWidth={2} />
              </button>
            </div>
          </div>

          {/* Meta strip with icons */}
          <div className="summary-meta-strip">
            <span className="summary-meta-item">
              <Hash size={11} strokeWidth={2.5} />
              {state.summary.wordCount.toLocaleString()} words
            </span>
            <span className="summary-meta-item">
              <Zap size={11} strokeWidth={2.5} />
              {state.summary.tokensUsed.toLocaleString()} tokens
            </span>
            {state.summary.processingTime > 0 && (
              <span className="summary-meta-item">
                <Clock size={11} strokeWidth={2.5} />
                {(state.summary.processingTime / 1000).toFixed(1)}s
              </span>
            )}
            {state.autoSaved && (
              <span className="summary-meta-item meta-saved">
                <CheckCircle2 size={11} strokeWidth={2.5} />
                Saved automatically
              </span>
            )}
          </div>

          <div
            id="summary-content"
            className="summary-text markdown-content"
            dangerouslySetInnerHTML={{ __html: renderMarkdown(state.summary.summary) }}
          />
        </div>
      )}

      {/* ---- Empty hint ---- */}
      {!state.summary && !state.isSummarizing && state.pageAccessible && (
        <div className="summarize-empty-hint" role="note">
          Choose a prompt below, then summarize this page. You can also right‑click selected text on any page.
        </div>
      )}

      {/* ---- Current page chip ---- */}
      <div className="current-page">
        <label>Current Page</label>
        <div id="current-url" className="url-display page-context-chip">
          {favicon ? (
            <img src={favicon} alt="" className="page-favicon" width={26} height={26} />
          ) : (
            <div className="page-favicon" aria-hidden />
          )}
          <div className="page-context-text">
            <div className="page-hostname">{hostname}</div>
            <div className="page-title-trunc">{state.currentTitle || 'Untitled'}</div>
          </div>
          <div className="page-context-actions">
            <button type="button" className="icon-btn-sm" onClick={copyPageUrl} title="Copy page URL">
              <Link2 size={13} />
            </button>
            <button type="button" className="icon-btn-sm" onClick={openCurrentPage} title="Open page in new tab">
              <ExternalLink size={13} />
            </button>
          </div>
        </div>

        {state.sentUrl && state.sentUrl !== state.currentUrl && (
          <details className="page-details">
            <summary>API URL details</summary>
            Sent to API: {state.sentUrl}
          </details>
        )}

        {!state.pageAccessible && (
          <div className="error-message show">
            <AlertTriangle size={13} style={{ display: 'inline', marginRight: 6, verticalAlign: 'middle' }} />
            This page cannot be summarized. Navigate to a regular https:// page.
            <div className="callout-actions">
              <button type="button" className="secondary-btn" onClick={initializeTab}>
                <RotateCcw size={12} style={{ display: 'inline', marginRight: 4, verticalAlign: 'middle' }} />
                Retry detection
              </button>
            </div>
          </div>
        )}

        {state.pageAccessible && state.domainWarning && (
          <div className="warning-message show">
            <AlertTriangle size={13} style={{ display: 'inline', marginRight: 6, verticalAlign: 'middle' }} />
            {state.domainWarning}
          </div>
        )}
      </div>

      {/* ---- Prompt section ---- */}
      <div className="prompt-section">
        <label>Choose Prompt</label>
        <div className="prompt-picker">
          {favoritePrompts.length > 0 && (
            <div className="prompt-segments" role="group" aria-label="Favorite prompts">
              {favoritePrompts.map(prompt => (
                <button
                  key={prompt.id}
                  type="button"
                  className={`prompt-segment ${state.selectedPrompt === prompt.id ? 'active' : ''}`}
                  onClick={() => selectPrompt(prompt.id)}
                  disabled={state.isSummarizing}
                  title={prompt.description}
                >
                  {prompt.name}
                </button>
              ))}
            </div>
          )}
          {morePrompts.length > 0 && (
            <select
              id="prompt-select"
              className="prompt-more-select"
              value={morePrompts.some(p => p.id === state.selectedPrompt) ? state.selectedPrompt : ''}
              onChange={e => e.target.value && selectPrompt(e.target.value)}
              disabled={state.isSummarizing}
              aria-label="More prompts"
            >
              <option value="" disabled>More prompts…</option>
              {morePrompts.map(prompt => (
                <option key={prompt.id} value={prompt.id}>{prompt.name}</option>
              ))}
            </select>
          )}
          {selectedPromptObj?.description && (
            <p className="prompt-description">{selectedPromptObj.description}</p>
          )}
        </div>
      </div>

      {/* ---- Summarize button ---- */}
      <button
        id="summarize-btn"
        className={`primary-btn full-width ${state.isSummarizing ? 'loading' : ''}`}
        onClick={handleSummarize}
        disabled={state.isSummarizing || !state.pageAccessible}
        type="button"
      >
        <span className={`btn-text ${state.isSummarizing ? 'hidden' : ''}`}>
          Summarize This Page
        </span>
        <span className={`btn-loading ${state.isSummarizing ? '' : 'hidden'}`}>
          <span className="loading-dots"><span /><span /><span /></span>
          Summarizing…
        </span>
      </button>

      {/* Disabled explanation note */}
      {!state.pageAccessible && !state.isSummarizing && (
        <p className="summarize-disabled-note" role="note">
          <Info size={12} strokeWidth={2} />
          Navigate to a regular web page or article to enable summarization.
        </p>
      )}

      {/* ---- Error ---- */}
      {state.error && (
        <div id="summary-error" className="error-message show" role="alert">
          {state.error}
          <div className="callout-actions">
            <button type="button" className="secondary-btn" onClick={handleSummarize} disabled={state.isSummarizing}>
              Retry
            </button>
            <a
              className="callout-link secondary-btn"
              href="https://www.get-tldr.com"
              target="_blank"
              rel="noopener noreferrer"
            >
              Help
            </a>
          </div>
        </div>
      )}
    </div>
  );
};
