/**
 * API Service for Get TLDR Chrome Extension
 * Handles all interactions with the Get TLDR API
 */

import { StorageService } from './storage';

export interface SummaryRequest {
  url: string;
  prompt?: string;
  skipCache?: boolean;
}

export interface SummaryResponse {
  summary: string;
  tokensUsed: number;
  processingTime: number;
  wordCount: number;
}

export interface UsageData {
  currentUsage: number;
  monthlyLimit: number;
  planType: string;
  resetDate: string;
}

export interface PromptOption {
  id: string;
  name: string;
  description: string;
  prompt: string;
}

interface ApiPromptResponse {
  id: string;
  title?: string;
  name?: string;
  description?: string;
  content?: string;
  prompt?: string;
}

export interface ApiValidationResponse {
  valid: boolean;
  planType?: string;
  usage?: UsageData;
}

export class ApiService {
  private static readonly BASE_URL = 'https://www.get-tldr.com/api/v1';
  private static readonly ENDPOINTS = {
    SUMMARIZE: '/summarize',
    USAGE: '/users/usage',
    PROMPTS: '/prompts',
    PROFILE: '/users/profile'
  } as const;

  /**
   * Validate API key by attempting to access profile endpoint
   */
  static async validateApiKey(apiKey: string): Promise<boolean> {
    try {
      const response = await fetch(`${this.BASE_URL}${this.ENDPOINTS.PROFILE}`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
          'X-API-Key': apiKey
        }
      });

      return response.ok;
    } catch (error) {
      console.error('API key validation failed:', error);
      return false;
    }
  }

  /**
   * Get available prompts (with caching)
   */
  static async getPrompts(apiKey: string, useCache: boolean = true): Promise<PromptOption[]> {
    // Try to get from cache first if enabled
    if (useCache) {
      const cached = await StorageService.getCachedPrompts();
      if (cached && Array.isArray(cached)) {
        // Return cached prompts immediately
        return cached;
      }
    }

    try {
      const response = await fetch(`${this.BASE_URL}${this.ENDPOINTS.PROMPTS}`, {
        method: 'GET',
        headers: {
          'X-API-Key': apiKey,
          'Content-Type': 'application/json'
        }
      });

      if (response.ok) {
        const data = await response.json();
        
        // Handle the actual API response structure
        if (data.prompts && Array.isArray(data.prompts)) {
          const apiPrompts = data.prompts.map((prompt: ApiPromptResponse) => ({
            id: prompt.id,
            name: prompt.title || prompt.name,
            description: prompt.description || '',
            prompt: prompt.content || prompt.prompt
          }));
          
          // Combine API prompts with default prompts
          const allPrompts = [...this.getDefaultPrompts(), ...apiPrompts];
          
          // Cache the result for 1 hour
          await StorageService.cachePrompts(allPrompts, 60);
          
          return allPrompts;
        }
        
        const defaultPrompts = this.getDefaultPrompts();
        await StorageService.cachePrompts(defaultPrompts, 60);
        return defaultPrompts;
      }

      // Fallback to default prompts if API fails
      const defaultPrompts = this.getDefaultPrompts();
      await StorageService.cachePrompts(defaultPrompts, 60);
      return defaultPrompts;
    } catch (error) {
      console.error('Failed to fetch prompts:', error);
      const defaultPrompts = this.getDefaultPrompts();
      await StorageService.cachePrompts(defaultPrompts, 60);
      return defaultPrompts;
    }
  }

  /**
   * Get default prompts as fallback
   */
  private static getDefaultPrompts(): PromptOption[] {
    return [
      {
        id: 'default',
        name: 'Default Summary',
        description: 'General purpose summary',
        prompt: 'Provide a concise summary of the main points in this content.'
      },
      {
        id: 'bullet-points',
        name: 'Bullet Points',
        description: 'Key points in bullet format',
        prompt: 'Summarize this content as bullet points highlighting the key information.'
      },
      {
        id: 'executive',
        name: 'Executive Summary',
        description: 'Business-focused summary',
        prompt: 'Create an executive summary focusing on business implications and key decisions.'
      },
      {
        id: 'technical',
        name: 'Technical Summary',
        description: 'Technical details and implementation',
        prompt: 'Summarize the technical aspects, implementation details, and key technical points.'
      },
      {
        id: 'action-items',
        name: 'Action Items',
        description: 'Actionable tasks and next steps',
        prompt: 'Extract actionable items, tasks, and next steps from this content.'
      }
    ];
  }

  /**
   * Summarize content
   */
  static async summarizeContent(apiKey: string, request: SummaryRequest): Promise<SummaryResponse> {
    try {
      const inputUrl = ApiService.canonicalizeUrl(request.url);
      const response = await fetch(`${this.BASE_URL}${this.ENDPOINTS.SUMMARIZE}`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-API-Key': apiKey
        },
        body: JSON.stringify({
          // Per API docs: input should be the URL (we send only the open page URL)
          input: inputUrl,
          system_prompt: request.prompt,
          ...(request.skipCache !== undefined ? { skip_cache: request.skipCache } : {})
        })
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.message || `API request failed with status ${response.status}`);
      }

      const data = await response.json();
      const tokensUsed =
        (typeof data.total_tokens === 'number' && data.total_tokens) ||
        (typeof data.input_tokens === 'number' && typeof data.output_tokens === 'number'
          ? data.input_tokens + data.output_tokens
          : 0);
      const processingTime =
        (data.processing_info && typeof data.processing_info.processing_time === 'number'
          ? data.processing_info.processing_time
          : 0);
      const wordCount = typeof data.summary === 'string' ? data.summary.trim().split(/\s+/).length : 0;
      return {
        summary: data.summary,
        tokensUsed,
        processingTime,
        wordCount
      };
    } catch (error) {
      console.error('Summarization failed:', error);
      throw new Error(error instanceof Error ? error.message : 'Failed to summarize content');
    }
  }

  /**
   * Canonicalize URLs for better API handling (e.g., normalize YouTube URLs to watch form)
   */
  static canonicalizeUrl(rawUrl: string): string {
    try {
      const url = new URL(rawUrl);
      const host = url.hostname.toLowerCase();

      // Normalize mobile domains
      if (host === 'm.youtube.com') {
        url.hostname = 'www.youtube.com';
      }

      // Handle youtu.be short links -> watch?v=
      if (host === 'youtu.be') {
        const videoId = url.pathname.replace(/^\//, '') || '';
        if (videoId) {
          const watch = new URL('https://www.youtube.com/watch');
          watch.searchParams.set('v', videoId);
          const t = url.searchParams.get('t') || url.searchParams.get('start');
          if (t) watch.searchParams.set('t', t);
          return watch.toString();
        }
      }

      // Handle shorts -> watch?v=
      if (host.endsWith('youtube.com') && url.pathname.startsWith('/shorts/')) {
        const videoId = url.pathname.split('/')[2] || '';
        if (videoId) {
          const watch = new URL('https://www.youtube.com/watch');
          watch.searchParams.set('v', videoId);
          return watch.toString();
        }
      }

      // Handle embed -> watch?v=
      if (host.endsWith('youtube.com') && url.pathname.startsWith('/embed/')) {
        const videoId = url.pathname.split('/')[2] || '';
        if (videoId) {
          const watch = new URL('https://www.youtube.com/watch');
          watch.searchParams.set('v', videoId);
          return watch.toString();
        }
      }

      return url.toString();
    } catch {
      return rawUrl;
    }
  }

  /**
   * Get usage statistics
   */
  static async getUsageData(apiKey: string): Promise<UsageData> {
    try {
      const response = await fetch(`${this.BASE_URL}${this.ENDPOINTS.USAGE}`, {
        method: 'GET',
        headers: {
          'X-API-Key': apiKey,
          'Content-Type': 'application/json'
        }
      });

      if (!response.ok) {
        throw new Error(`Usage request failed with status ${response.status}`);
      }

      const data = await response.json();
      
      // Calculate reset date (assuming monthly billing cycle)
      const now = new Date();
      const resetDate = new Date(now.getFullYear(), now.getMonth() + 1, 1);
      
      return {
        currentUsage: data.monthly_used || 0,
        monthlyLimit: data.monthly_limit || 0,
        planType: 'API', // Default since not provided in API response
        resetDate: resetDate.toISOString()
      };
    } catch (error) {
      console.error('Failed to fetch usage data:', error);
      throw new Error('Failed to retrieve usage information');
    }
  }

  /**
   * Check if current page is accessible for content extraction
   */
  static async isPageAccessible(): Promise<boolean> {
    try {
      const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
      
      if (!tab.url) return false;
      
      // Check for restricted URLs
      const restrictedProtocols = ['chrome://', 'chrome-extension://', 'moz-extension://', 'edge://'];
      return !restrictedProtocols.some(protocol => tab.url!.startsWith(protocol));
    } catch (error) {
      console.error('Failed to check page accessibility:', error);
      return false;
    }
  }
}